// ⚙️ Edit these values before running
return [{
  json: {
    case_id: '102'
  }
}];

const raw = $input.first().json;
const caseData = raw.data ?? raw;

const summary =
  caseData.case?.description ??
  caseData.case?.case_description ??
  caseData.case_description ??
  caseData.summary ??
  null;

return [{
  json: {
    ...raw,
    case_id: $('Set Config').first().json.case_id,
    case_name: caseData.case?.name ?? caseData.case_name ?? `Case ${$('Set Config').first().json.case_id}`,
    _summary_found: !!summary,
    _summary_text: summary,
    _prompt_count: summary && summary.includes('{{AI_PROMPT:')
      ? (summary.match(/\{\{AI_PROMPT:/g) ?? []).length
      : 0,
    _parsed_prompts: []
  }
}];

const item    = $input.first().json;
const summary = item._summary_text;

if (!summary) {
  return [{ json: { ...item, _parsed_prompts: [] } }];
}

const lines         = summary.split('\n');
const headingRe     = /^#{1,6}\s+.+/;
const promptStartRe = /\{\{AI_PROMPT:/;

const parsedPrompts = [];
let currentHeading  = '(preamble)';
let i = 0;

while (i < lines.length) {
  const line = lines[i];

  if (headingRe.test(line.trim())) {
    currentHeading = line.trim();
    i++;
    continue;
  }

  if (promptStartRe.test(line)) {
    const blockLines = [line];
    let j = i + 1;
    while (j < lines.length && !blockLines.join('').includes('}}')) {
      blockLines.push(lines[j]);
      j++;
    }
    const fullBlock  = blockLines.join('\n');
    const innerMatch = fullBlock.match(/\{\{AI_PROMPT:\s*([\s\S]*?)\}\}/);
    if (innerMatch) {
      parsedPrompts.push({
        index:       parsedPrompts.length,
        heading:     currentHeading,
        prompt:      innerMatch[1].trim(),
        placeholder: fullBlock
      });
    }
    i = j;
    continue;
  }
  i++;
}

return [{
  json: {
    ...item,
    _prompt_count:   parsedPrompts.length,
    _parsed_prompts: parsedPrompts
  }
}];

const item = $input.first().json;
const raw  = item.data ?? {};

if (!raw || typeof raw !== 'object') {
  throw new Error('No DFIR-IRIS case data found.');
}

const caseMeta = raw.case ?? {};

const assets = (raw.assets ?? []).map(a => ({
  asset_id: a.asset_id,
  asset_uuid: a.asset_uuid,
  name: a.asset_name,
  type: a.type,
  ip: a.asset_ip || undefined,
  domain: a.asset_domain || undefined,
  compromise_status: a.asset_compromise_status || undefined,
  analysis_status: a.analysis_status || undefined,
  description: a.asset_description || undefined,
}));

const iocs = (raw.iocs ?? []).map(i => ({
  ioc_id: i.ioc_id,
  ioc_uuid: i.ioc_uuid,
  value: i.ioc_value || undefined,
  type: i.type_name ?? i.ioc_type?.type_name ?? i.ioc_type ?? undefined,
  tlp: i.tlp_name || undefined,
  description: i.ioc_description || undefined,
  tags: i.ioc_tags || undefined,
}));

const timeline = (raw.timeline ?? []).map(e => ({
  event_id: e.event_id,
  date: e.event_date,
  title: e.event_title,
  category: e.category || undefined,
  content: e.event_content || undefined,
  source: e.event_source || undefined,
  flagged: e.event_is_flagged || undefined,
  linked_assets: (e.assets ?? []).map(a => a.asset_name ?? a.name).filter(Boolean),
  linked_ioc_count: (e.iocs ?? []).length,
}));

const tasks = (raw.tasks ?? []).map(t => ({
  task_id: t.task_id,
  title: t.task_title,
  status: t.task_status,
  description: t.task_description || undefined,
  assignees: (t.task_assignees ?? []).map(a => a.name ?? a.user_name).filter(Boolean),
  open_date: t.task_open_date || undefined,
  close_date: t.task_close_date || undefined,
}));

const notes = (raw.notes ?? []).map(n => ({
  note_id: n.note_id,
  group: n.group_title,
  title: n.note_title,
  content: (n.note_content ?? '').substring(0, 4000),
}));

const evidence = (raw.evidences ?? []).map(e => ({
  evidence_id: e.evidence_id,
  filename: e.filename,
  filetype: e.filetype || undefined,
  date_added: e.date_added || undefined,
  added_by: e.added_by || undefined,
  description: e.description || undefined,
}));

const sharedContext = {
  case: {
    id: item.case_id,
    name: item.case_name,
    open_date: caseMeta.open_date,
    status: caseMeta.status_name,
    soc_id: caseMeta.soc_id,
    opened_by: caseMeta.opened_by,
    for_customer: caseMeta.for_customer,
    description: caseMeta.description,
    export_date: raw.export_date
  }
};

const configs = [
  {
    subagent: 'notes',
    instruction: 'Review analyst notes. Extract confirmed facts, analyst hypotheses, contradictions, missing context, and any action items embedded in notes. Treat notes as lower-confidence unless corroborated.',
    payload: { ...sharedContext, notes: notes.slice(0, 30) }
  },
  {
    subagent: 'assets',
    instruction: 'Review asset records. Extract scope, affected systems, compromise indicators, notable gaps in host context, and asset-level prioritisation for containment or collection.',
    payload: { ...sharedContext, assets }
  },
  {
    subagent: 'iocs',
    instruction: 'Review IoCs. Extract notable indicators, types, TLP implications, clustering/patterns, investigative value, and any obvious enrichment or validation follow-ups.',
    payload: { ...sharedContext, iocs }
  },
  {
    subagent: 'timeline',
    instruction: 'Review timeline events. Build a concise chronology, identify confirmed milestones, sequencing gaps, timestamp issues, and investigative inflection points.',
    payload: { ...sharedContext, timeline: timeline.slice(0, 75) }
  },
  {
    subagent: 'tasks',
    instruction: 'Review tasks. Extract outstanding work, completed actions, ownership gaps, blockers, and what should be prioritised next based on current task state.',
    payload: { ...sharedContext, tasks }
  },
  {
    subagent: 'evidence',
    instruction: 'Review evidence inventory. Extract what has been preserved, what appears missing, likely forensic collection gaps, and preservation priorities.',
    payload: { ...sharedContext, evidence }
  }
];

return configs.map(cfg => ({
  json: {
    case_id: item.case_id,
    case_name: item.case_name,
    _summary_found: item._summary_found,
    _summary_text: item._summary_text,
    _prompt_count: item._prompt_count,
    _parsed_prompts: item._parsed_prompts,
    subagent: cfg.subagent,
    subagent_instruction: cfg.instruction,
    payload_json: JSON.stringify(cfg.payload)
  }
}));

const agentItem = $input.first().json;
const loopItem  = $('Loop Category Items').item.json;

const analysis =
  agentItem.output ??
  agentItem.text ??
  JSON.stringify(agentItem);

return [{
  json: {
    case_id: loopItem.case_id,
    case_name: loopItem.case_name,
    _summary_found: loopItem._summary_found,
    _summary_text: loopItem._summary_text,
    _prompt_count: loopItem._prompt_count,
    _parsed_prompts: loopItem._parsed_prompts,
    subagent: loopItem.subagent,
    analysis: analysis.trim()
  }
}];

const raw = $input.first().json;

let items;
if (Array.isArray(raw.data)) {
  items = raw.data.map(entry => entry.json ?? entry);
} else {
  items = $input.all().map(i => i.json);
}

if (!items.length) {
  throw new Error('No sub-agent outputs received.');
}

const byName = Object.fromEntries(items.map(i => [i.subagent, i]));

const structured = {
  case_id: items[0].case_id,
  case_name: items[0].case_name,
  notes_analysis:    byName.notes?.analysis ?? 'No notes analysis returned.',
  assets_analysis:   byName.assets?.analysis ?? 'No assets analysis returned.',
  iocs_analysis:     byName.iocs?.analysis ?? 'No iocs analysis returned.',
  timeline_analysis: byName.timeline?.analysis ?? 'No timeline analysis returned.',
  tasks_analysis:    byName.tasks?.analysis ?? 'No tasks analysis returned.',
  evidence_analysis: byName.evidence?.analysis ?? 'No evidence analysis returned.'
};

const promptCarrier = items.find(i => Array.isArray(i._parsed_prompts)) ?? items[0];

return [{
  json: {
    case_id: promptCarrier.case_id,
    case_name: promptCarrier.case_name,
    template_summary: promptCarrier._summary_text,
    _summary_found: promptCarrier._summary_found,
    _prompt_count: promptCarrier._prompt_count,
    _parsed_prompts: promptCarrier._parsed_prompts ?? [],
    structured_context: JSON.stringify(structured, null, 2)
  }
}];

const item    = $input.first().json;
const prompts = item._parsed_prompts ?? [];

if (!prompts.length) {
  return [{
    json: {
      ...item,
      _no_prompts: true
    }
  }];
}

return prompts.map(p => ({
  json: {
    case_id: item.case_id,
    case_name: item.case_name,
    template_summary: item.template_summary,
    structured_context: item.structured_context,
    section_index: p.index,
    section_heading: p.heading,
    section_prompt: p.prompt,
    prompt_placeholder: p.placeholder
  }
}));

const agentItem = $input.first().json;
const loopItem  = $('Loop Prompt Items').item.json;

const generatedText =
  agentItem.output ??
  agentItem.text ??
  '[Section generation failed — no content returned]';

return [{
  json: {
    case_id: loopItem.case_id,
    case_name: loopItem.case_name,
    template_summary: loopItem.template_summary,
    section_index: loopItem.section_index,
    section_heading: loopItem.section_heading,
    prompt_placeholder: loopItem.prompt_placeholder,
    generated_text: generatedText.trim()
  }
}];

const raw = $input.first().json;

let items;
if (Array.isArray(raw.data)) {
  items = raw.data.map(entry => entry.json ?? entry);
} else {
  items = $input.all().map(i => i.json);
}

if (!items.length) throw new Error('Assembler received no items.');

if (items[0]?._no_prompts) {
  return [{
    json: {
      case_id: items[0].case_id,
      case_name: items[0].case_name,
      summary_markdown: null,
      _skipped: true,
      _reason: 'No {{AI_PROMPT}} blocks found in case summary'
    }
  }];
}

const templateSummary = items.find(i => i.template_summary)?.template_summary;
if (!templateSummary) {
  throw new Error('Assembler: no template_summary found on any item.');
}

const sorted  = [...items].sort((a, b) => (a.section_index ?? 0) - (b.section_index ?? 0));
const reverse = [...sorted].reverse();

let assembled = templateSummary;

for (const section of reverse) {
  if (!section.prompt_placeholder) continue;
  if (!assembled.includes(section.prompt_placeholder)) continue;
  assembled = assembled.replace(section.prompt_placeholder, section.generated_text ?? '');
}

assembled = assembled.replace(/\[CASE TITLE\]/g, items[0].case_name ?? 'Unknown Case');

return [{
  json: {
    case_id: items[0].case_id,
    case_name: items[0].case_name,
    summary_markdown: assembled
  }
}];

const result = $input.first().json;

const success = result.status === 1 || result.data !== undefined || result.success === true;

return [{
  json: {
    status: success ? 'success' : 'warning',
    case_id: $('Assemble Summary').first().json.case_id,
    case_name: $('Assemble Summary').first().json.case_name,
    message: success
      ? `Summary written to IRIS case #${$('Assemble Summary').first().json.case_id} — "${$('Assemble Summary').first().json.case_name}".`
      : `Summary generated but IRIS write response was unexpected. Verify case #${$('Assemble Summary').first().json.case_id} manually.`,
    iris_response: result
  }
}];
